  activityResource?: Prisma.ActivityResourceOmit;
  assignment?: Prisma.AssignmentOmit;
  assignmentTarget?: Prisma.AssignmentTargetOmit;
  contentPackage?: Prisma.ContentPackageOmit;
  activityProgress?: Prisma.ActivityProgressOmit;
  question?: Prisma.QuestionOmit;
  activityAttempt?: Prisma.ActivityAttemptOmit;
  submission?: Prisma.SubmissionOmit;
